def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_d = 0
    opp_d = 0
    recent5_d = 0
    recent10_d = 0

    start5 = n - 5
    if start5 < 0:
        start5 = 0
    start10 = n - 10
    if start10 < 0:
        start10 = 0

    for i in range(n):
        mine, opp = history[i]
        if mine == 'D':
            my_d += 1
        if opp == 'D':
            opp_d += 1
            if i >= start5:
                recent5_d += 1
            if i >= start10:
                recent10_d += 1

    last_me, last_opp = history[-1]

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    # Exploit opponents that have never defected.  The first 'D' is a probe;
    # the following 'C' gives them one full round to punish it.  If they still
    # never defect, switch to full exploitation.
    if opp_d == 0:
        if my_d == 0:
            if n == 1:
                return 'D'
            return 'C'
        if n == 2:
            return 'C'
        return 'D'

    # Always-defecting opponent: defect, it is payoff-dominant.
    if opp_d == n:
        return 'D'

    # Very strongly defective recent behavior: stop trying to repair.
    if recent10_d >= 9:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            # We are in mutual defection.  Usually offer cooperation to break
            # TFT-style loops, but if the opponent has a long unbroken defect
            # streak, treat it as a persistent defector.
            if opp_streak >= 4 and recent5_d >= 4:
                return 'D'
            return 'C'

        # We cooperated last round while they defected.  Forgive an isolated
        # provocation, but punish repeated or dense defection.
        if opp_streak >= 2 or recent5_d >= 3:
            return 'D'
        return 'C'

    # Opponent cooperated: normally stay cooperative unless already in
    # unconditional-exploiter mode above.
    return 'C'
